REQUEST_SCHEMA = {
    "type": "object",
    "description": "Return a concise local response for the declared intent.",
    "additionalProperties": False,
    "properties": {
        "request": {"type": "string", "minLength": 1, "maxLength": 2000}
    },
    "required": ["request"],
}

import json

from .schemas import REQUEST_SCHEMA

PLUGIN_NAME = "agent-plugin"
PLUGIN_INTENT = "An agent skill."

def handle(arguments, **kwargs):
    del kwargs
    try:
        request = arguments["request"]
        if not isinstance(request, str):
            raise ValueError("request must be text")
        value = request.strip()
        if not value or len(value) > 2000:
            raise ValueError("request must contain 1 to 2000 characters")
        return json.dumps({"intent": PLUGIN_INTENT, "result": f"{PLUGIN_NAME}: {value}"}, ensure_ascii=False)
    except (KeyError, TypeError, ValueError) as error:
        return json.dumps({"error": str(error)}, ensure_ascii=False)

def register(ctx):
    ctx.register_tool(
        name=f"{PLUGIN_NAME}.respond",
        toolset=PLUGIN_NAME,
        schema=REQUEST_SCHEMA,
        handler=handle,
    )
